import assert from 'node:assert/strict';
import test from 'node:test';
import {readFileSync} from 'node:fs';
import {parseAutoTrace} from '../service/battle-trace.ts';
import {validateAutoTrace,pausedAutoTraceMatchesState} from '../web/auto-battle.js';
// Actual serialized native traces from explicit synthetic, native-valid trained
// states; generated by final-auto-20261012/core/fixtures.cpp, never hardware saves.
const fixtures=JSON.parse(readFileSync(new URL('./fixtures/auto-current-traces.json',import.meta.url),'utf8'));
for(const f of fixtures)test(`native Auto trace level ${f.fixtureLevel}, HP ${f.trace.player.combat.maxHp}, sequence ${f.trace.startSequence} crosses both boundaries`,()=>{
  assert.equal(f.trace.startSequence,f.before.sequence);assert.equal(f.trace.endSequence,f.state.sequence);
  assert.deepEqual(parseAutoTrace(f.trace,'wild'),f.trace);
  assert.deepEqual(validateAutoTrace(f.trace,'wild'),f.trace);
  assert(pausedAutoTraceMatchesState(f.trace,f.state));
});
test('current Auto bounds still reject out-of-range native-looking records',()=>{
  for(const mutate of [
    (t:any)=>t.player.level=100,(t:any)=>t.enemy.level=0,
    (t:any)=>t.player.combat.maxHp=2049,(t:any)=>t.enemy.combat.magic=257,
    (t:any)=>t.steps[0].playerHpBefore=2049,
    (t:any)=>{t.startSequence=0xffffffff;t.endSequence=0x100000000;},
    (t:any)=>t.startSequence=-1,(t:any)=>t.steps[0].enemyHpAfter=-1,
  ]){const t=structuredClone(fixtures[0].trace);mutate(t);assert.throws(()=>parseAutoTrace(t,'wild'));assert.throws(()=>validateAutoTrace(t,'wild'));}
});
